            printf("                               directory.\n");
            printf("      --extra=KEY=VALUE,...    Extra variables passed to the templates.\n");
            printf("      --template=PATH          Custom template used to render the note.\n");
            printf("  -p, --print-path             Print the path of the created note instead of\n");
            printf("                               editing it.\n");
            printf("  -n, --dry-run                Don't actually create the note. Instead, prints\n");
            printf("                               its content on stdout and the generated path on\n");
            printf("                               stderr.\n");
            printf("      --id=ID                  Skip id generation and use provided value.\n");
            return 0;
        }
    }

