        if (argc == 1 || (argc >= 2 && (strcmp(argv[2], "-h") == 0 || strcmp(argv[2], "--help") == 0))) {
            printf("Usage: zk list [<path> ...]\n\n");
            printf("List notes matching the given criteria.\n\n");
            printf("Arguments:\n");
            printf("  [<path> ...]    Find notes matching the given path, including its descendants.\n\n");
            printf("Flags:\n");
            printf("  -h, --help                 Show context-sensitive help.\n");
            printf("      --notebook-dir=PATH    Turn off notebook auto-discovery and set manually\n");
            printf("                             the notebook where commands are run.\n");
            printf("  -W, --working-dir=PATH     Run as if zk was started in <PATH> instead of the\n");
            printf("                             current working directory.\n");
            printf("      --no-input             Never prompt or ask for confirmation.\n\n");
            printf("Formatting\n");
            printf("  -f, --format=TEMPLATE    Pretty print the list using a custom template or one\n");
            printf("                           of the predefined formats: oneline, short, medium,\n");
            printf("                           long, full, json, jsonl.\n");
            printf("      --header=STRING      Arbitrary text printed at the start of the list.\n");
            printf("      --footer=\\\"\\n\\\"       Arbitrary text printed at the end of the list.\n");
            printf("  -d, --delimiter=\\\"\\n\\\"     Print notes delimited by the given separator.\n");
            printf("  -0, --delimiter0         Print notes delimited by ASCII NUL characters. This\n");
            printf("                           is useful when used in conjunction with `xargs -0`.\n");
            printf("  -P, --no-pager           Do not pipe output into a pager.\n");
            printf("  -q, --quiet              Do not print the total number of notes found.\n\n");
            printf("Filtering\n");
            printf("  -i, --interactive                Select notes interactively with fzf.\n");
            printf("  -n, --limit=COUNT                Limit the number of notes found.\n");
            printf("  -m, --match=QUERY,...            Terms to search for in the notes.\n");
            printf("  -M, --match-strategy=STRATEGY    Text matching strategy among: fts, re, exact.\n");
            printf("  -x, --exclude=PATH,...           Ignore notes matching the given path,\n");
            printf("                                   including its descendants.\n");
            printf("  -t, --tag=TAG,...                Find notes tagged with the given tags.\n");
            printf("      --mention=PATH,...           Find notes mentioning the title of the given\n");
            printf("                                   ones.\n");
            printf("      --mentioned-by=PATH,...      Find notes whose title is mentioned in the\n");
            printf("                                   given ones.\n");
            printf("  -l, --link-to=PATH,...           Find notes which are linking to the given\n");
            printf("                                   ones.\n");
            printf("      --no-link-to=PATH,...        Find notes which are not linking to the given\n");
            printf("                                   notes.\n");
            printf("  -L, --linked-by=PATH,...         Find notes which are linked by the given\n");
            printf("                                   ones.\n");
            printf("      --no-linked-by=PATH,...      Find notes which are not linked by the given\n");
            printf("                                   ones.\n");
            printf("      --orphan                     Find notes which are not linked by any other\n");
            printf("                                   note.\n");
            printf("      --tagless                    Find notes which have no tags.\n");
            printf("      --missing-backlink           Find notes with at least one missing\n");
            printf("                                   backlink.\n");
            printf("      --related=PATH,...           Find notes which might be related to the\n");
            printf("                                   given ones.\n");
            printf("      --max-distance=COUNT         Maximum distance between two linked notes.\n");
            printf("  -r, --recursive                  Follow links recursively.\n");
            printf("      --created=DATE\n");
            printf("      --created-before=DATE        Find notes created before the given date.\n");
            printf("      --created-after=DATE         Find notes created after the given date.\n");
            printf("      --modified=DATE              Find notes modified on the given date.\n");
            printf("      --modified-before=DATE       Find notes modified before the given date.\n");
            printf("      --modified-after=DATE        Find notes modified after the given date.\n\n");
            printf("Sorting\n");
            printf("  -s, --sort=TERM,...    Order the notes by the given criterion.\n");
            return 0;
        }
    }

    if (strcmp(argv[1], "tag") == 0) {
        if (argc >= 2 && (argc == 2 || (argc == 3 && (strcmp(argv[2], "-h") == 0 || strcmp(argv[2], "--help") == 0)))) {
